import{_ as c,r as e,o as i,c as u,e as o,a as n,s as t,d as s}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"组件 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"介绍","slug":"介绍","link":"#介绍","children":[]},{"level":2,"title":"组件别名","slug":"组件别名","link":"#组件别名","children":[]},{"level":2,"title":"使用外部属性值","slug":"使用外部属性值","link":"#使用外部属性值","children":[]},{"level":2,"title":"将变量传递给组件","slug":"将变量传递给组件","link":"#将变量传递给组件","children":[]},{"level":2,"title":"自定义默认标记","slug":"自定义默认标记","link":"#自定义默认标记","children":[{"level":3,"title":"将默认标记移动到部件","slug":"将默认标记移动到部件","link":"#将默认标记移动到部件","children":[]},{"level":3,"title":"覆盖组件部件","slug":"覆盖组件部件","link":"#覆盖组件部件","children":[]}]},{"level":2,"title":"\\"ViewBag\\"组件","slug":"viewbag-组件","link":"#viewbag-组件","children":[{"level":3,"title":"AJAX 处理程序和部件","slug":"ajax-处理程序和部件","link":"#ajax-处理程序和部件","children":[]}]}],"relativePath":"2.x/zh-cn/cms/components.md","filePath":"2.x/zh-cn/cms/components.md"}'),r={name:"2.x/zh-cn/cms/components.md"};function g(d,a,k,m,v,h){const p=e("pre-heading"),l=e("post-heading");return i(),u("div",null,[o(p),a[0]||(a[0]=n("h1",null,"组件",-1)),o(l),a[1]||(a[1]=t(`<p>组件是可配置的构建元素，可以附加到任何页面、部件或布局。组件是October的主要功能。每个组件都实现了一些扩展您网站的功能。组件可以在页面上输出 HTML 标记，但这不是必需的 - 组件的其他重要功能是处理 <a href="./../ajax/introduction.html">AJAX 请求</a>、处理表单回发和处理页面执行周期，这允许向页面注入变量或实现网站安全。</p><p>本文介绍了组件的基础知识，并没有解释如何使用 <a href="./../ajax/handlers.html">AJAX组件</a> 或 <a href="./../plugin/components.html">开发组件</a> 作为插件的一部分。</p><blockquote><p><strong>注意</strong>：在局部组件中使用组件的功能有限，<a href="./partials.html#oc-dynamic-partials">动态局部组件</a> 文章中对此进行了更详细的描述。</p></blockquote><h2 id="介绍"><a href="#介绍" class="header-anchor">#</a> 介绍</h2><p>如果您使用后端用户界面，您可以通过单击&quot;组件&quot;面板中的组件将组件添加到您的页面、部件和布局。如果您使用文本编辑器，您可以通过将组件名称添加到模板文件的 <a href="./themes.html#oc-configuration-section">Configuration</a> 部分，将组件附加到页面或布局。下一个示例演示如何向页面添加演示 To-do 组件：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Components demonstration</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/components</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>这将使用组件部分中定义的属性初始化组件。许多组件都有属性，但这不是必需的。有些属性是必需的，有些属性有默认值。如果您不确定某个组件支持哪些属性，请参阅开发人员提供的文档，或使用 October 后端中的检查器。单击页面或布局组件面板中的组件时，检查器会打开。</p><p>当您引用一个组件时，它会自动创建一个与组件名称匹配的页面变量(上一个示例中的<code>demoTodo</code>)。提供 HTML 标记的组件可以在带有 <code>{% component %}</code> 标签的页面上呈现，如下所示：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><blockquote><p><strong>注意</strong>：如果将两个同名组件一起分配给一个页面和布局，页面组件会覆盖布局组件的任何属性。</p></blockquote><p><a id="oc-components-aliases"></a></p><h2 id="组件别名"><a href="#组件别名" class="header-anchor">#</a> 组件别名</h2><p>如果有两个插件注册了同名的组件，您可以通过使用其完全限定的类名并为其分配一个 <em>alias</em> 来附加一个组件：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">October\\Demo\\Components\\Todo demoTodoAlias</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><p>该部分中的第一个参数是类名，第二个是附加到页面时将使用的组件别名。如果指定了组件别名，则在引用组件时应在页面代码中的任何地方使用别名。请注意，下一个示例引用了组件别名：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>别名还允许您首先使用短名称，然后使用别名，在同一页面上定义同一类的多个组件。这使您可以在页面上使用同一组件的多个实例。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoA</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">10</span>
<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoB</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><p><a id="oc-using-external-property-values"></a></p><h2 id="使用外部属性值"><a href="#使用外部属性值" class="header-anchor">#</a> 使用外部属性值</h2><p>默认情况下，属性值在定义组件的配置部分初始化，并且属性值是静态的，如下所示：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,22)),a[2]||(a[2]=n("div",null,[n("p",null,[s("但是，有一种方法可以使用从外部参数加载的值来初始化属性 - URL 参数或 "),n("a",{href:"./partials.html"},"partial"),s(" 参数(对于在部件中定义的组件)。对应部件变量加载的值使用 "),n("code",{"v-pre":""},"{{ paramName }}"),s(" 语法：")])],-1)),a[3]||(a[3]=t(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>假设在上面的示例中，组件 <strong>demoTodo</strong> 定义在一个部件中，它将使用从 <strong>maxItems</strong> 部件变量加载的值进行初始化：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>my-todo-partial<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>10<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>您可以使用点表示法从外部参数中检索深度嵌套的值：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ data.maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,5)),a[4]||(a[4]=n("div",null,[n("p",null,[s("要从 URL 参数加载属性值，请使用 "),n("code",{"v-pre":""},"{{ :paramName }}"),s(" 语法，其中名称以冒号 ("),n("code",{"v-pre":""},":"),s(") 开头，例如：")])],-1)),a[5]||(a[5]=t(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ :maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>组件所属的页面应该有一个对应的<a href="./pages.html#oc-url-syntax">URL参数</a>定义：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/todo/:maxItems</span>&quot;</span>
</code></pre></div><p>在 October的后端中，您可以使用 检查器(Inspector) 工具为组件属性分配外部值。在检查器中，您不需要使用大括号输入参数名称。 检查器中的每个字段在右侧都有一个图标，用于打开外部参数名称编辑器。对于部件变量，输入参数名称为 <code>paramName</code>，或者为 URL 参数输入 <code>:paramName</code>。</p><p><a id="oc-passing-variables-to-components"></a></p><h2 id="将变量传递给组件"><a href="#将变量传递给组件" class="header-anchor">#</a> 将变量传递给组件</h2><p>组件可以设计成在渲染的时候使用变量，类似于<a href="./partials.html#oc-passing-variables-to-partials">部件变量</a>，可以在<code>{% component %}</code> 中的组件名后指定标签。指定的变量将显式覆盖 <a href="./../plugin/components.html#oc-component-properties">组件属性</a> 的值，包括 <a href="#oc-using-external-property-values">外部属性值</a>。</p><p>在此示例中，组件的 <strong>maxItems</strong> 属性将在组件呈现时设置为 <em>7</em>：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>7<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><blockquote><p><strong>注意</strong>：并非所有组件都支持渲染时传递变量。</p></blockquote><h2 id="自定义默认标记"><a href="#自定义默认标记" class="header-anchor">#</a> 自定义默认标记</h2><p>组件提供的标记通常用作组件的使用示例。在某些情况下，您可能希望修改组件的外观和输出。 <a href="#oc-moving-default-markup-to-a-partial">将默认标记移动到主题部分</a> 适用于彻底检修组件。 <a href="#oc-overriding-component-partials">覆盖组件部分</a> 对局部区域进行自定义很有用。</p><p><a id="oc-moving-default-markup-to-a-partial"></a></p><h3 id="将默认标记移动到部件"><a href="#将默认标记移动到部件" class="header-anchor">#</a> 将默认标记移动到部件</h3><p>每个组件都可以有一个名为 <strong>default.htm</strong> 的入口点部分，它会在调用 <code>{% component %}</code> 标签时呈现，在以下示例中，我们假设组件名为 <strong>blogPost</strong>。</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;blog/post&quot;

[blogPost]
==
{% component &quot;blogPost&quot; %}
</code></pre></div><p>输出将从插件目录 <strong>components/blogpost/default.htm</strong> 呈现。您可以复制此文件中的所有标记并将其直接粘贴到页面中或粘贴到新的部件，例如 <strong>blog-post.htm</strong>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>在标记中，您可能会注意到对名为 <code>__SELF__</code> 的变量的引用，它指的是组件对象，应该替换为页面上使用的组件别名，在本例中为 <code>blogPost</code>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>这是允许默认组件标记在主题内的任何位置工作所需的唯一更改。现在可以使用主题部件自定义和呈现组件标记。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog-post.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>对于在组件部分目录中找到的所有其他部件，可以重复此过程。</p><p><a id="oc-overriding-component-partials"></a></p><h3 id="覆盖组件部件"><a href="#覆盖组件部件" class="header-anchor">#</a> 覆盖组件部件</h3><p>可以使用主题部件覆盖所有组件部件。如果名为 <strong>channel</strong> 的组件使用 <strong>title.htm</strong> 部件。</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;mypage&quot;

[channel]
==
{% component &quot;channel&quot; %}
</code></pre></div><p>我们可以通过在我们的主题中创建一个名为 <strong>partials/channel/title.htm</strong> 的文件来覆盖部件。</p><p>文件路径段分解如下：</p><div class="table"><table tabindex="0"><thead><tr><th>标识</th><th>描述</th></tr></thead><tbody><tr><td><strong>partials</strong></td><td>主题部件目录</td></tr><tr><td><strong>channel</strong></td><td>组件别名(部件子目录)</td></tr><tr><td><strong>title.htm</strong></td><td>要覆盖的组件部件</td></tr></tbody></table></div><p>通过简单地为组件分配同名别名，可以将部件子目录名称自定义为任何内容。例如，通过为 <strong>channel</strong> 组件分配一个不同的别名 <strong>foobar</strong>，覆盖目录也会改变：</p><div class="language- extra-class"><pre class="language-text"><code>[channel foobar]
==
{% component &quot;foobar&quot; %}
</code></pre></div><p>现在我们可以通过在我们的主题中创建一个名为 <strong>partials/foobar/title.htm</strong> 的文件来覆盖 <strong>title.htm</strong> 部件。</p><h2 id="viewbag-组件"><a href="#viewbag-组件" class="header-anchor">#</a> &quot;ViewBag&quot;组件</h2><p>October包含一个名为&quot;ViewBag&quot;的特殊组件，可用于任何页面或布局。它允许在标记区域内轻松定义和访问临时属性作为变量。一个很好的用法示例是在页面内定义活动菜单项：</p><div class="language- extra-class"><pre class="language-text"><code>title = &quot;About&quot;
url = &quot;/about.html&quot;
layout = &quot;default&quot;

[viewBag]
activeMenu = &quot;about&quot;
==

&lt;p&gt;页面内容...&lt;/p&gt;
</code></pre></div><p>然后使用 <code>viewBag</code> 变量在页面、布局或部件标记中使为组件定义的任何属性可用。例如，在此布局中，如果 <code>viewBag.activeMenu</code> 值设置为 <strong>about</strong>，则会将 <strong>active</strong> 类添加到列表项中：</p><div class="language- extra-class"><pre class="language-text"><code>description = &quot;默认布局&quot;
==
[...]

&lt;!-- Main navigation --&gt;
&lt;ul&gt;
    &lt;li class=&quot;{{ viewBag.activeMenu == &#39;about&#39; ? &#39;active&#39; }}&quot;&gt;About&lt;/li&gt;
    [...]
&lt;/ul&gt;
</code></pre></div><blockquote><p><strong>注意</strong>：viewBag 组件隐藏在后端，仅可用于基于文件的编辑。 其他插件也可以使用它来存储数据。</p></blockquote><h3 id="ajax-处理程序和部件"><a href="#ajax-处理程序和部件" class="header-anchor">#</a> AJAX 处理程序和部件</h3><p>组件可以将 <a href="./../ajax/introduction.html">AJAX 处理程序</a> 和 <a href="./../cms/partials.html">partials</a> 引入主题的生命周期，使用组件名称的前缀和两个 <code>::</code> 符号。 例如，组件定义的所有 AJAX 处理程序都是全局可用的。</p><div class="language- extra-class"><pre class="language-text"><code>data-request=&quot;onMyComponentHandler&quot;
</code></pre></div><p>但是，如果命名存在冲突，则可以使用完全限定名称。</p><div class="language- extra-class"><pre class="language-text"><code>data-request=&quot;componentName::onMyComponentHandler&quot;
</code></pre></div><p>从组件外部呈现的部件必须使用其完全限定名称。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>componentName::component-partial<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>阅读更多关于 <a href="./../plugin/components.html#oc-component-partials">组件开发</a> 以了解组件部分。</p>`,47))])}const _=c(r,[["render",g]]);export{w as __pageData,_ as default};
